import numpy as np
from scipy.spatial.transform import Rotation
from scipy.optimize import differential_evolution
D=np.load('assembly.npz'); orig=D['coords']; elems=D['elems']
rad={'H':1.2,'C':1.7,'O':1.52,'N':1.55,'F':1.47,'Ge':2.11,'Au':1.66,'Cl':1.75}
radii=np.array([rad[e] for e in elems]);pairs=[]
frags=[np.arange(3,21),np.arange(21,39),np.arange(40,58),np.arange(58,76)]
for fi in range(4):
 for fj in range(fi):
  for i in frags[fi]:
   for j in frags[fj]:pairs.append((i,j))
inds=np.array(pairs); rcut=(radii[inds[:,0]]+radii[inds[:,1]])*.87

def transform(angs):
 p=orig.copy()
 for g,deg in zip([2,39],angs):
  a=-p[g]/np.linalg.norm(p[g]);R=Rotation.from_rotvec(a*np.radians(deg)).as_matrix(); ids=np.arange(g+1,g+37)
  p[ids]=(p[ids]-p[g])@R.T+p[g]
 return p

def loss(angs):
 p=transform(angs);d=np.linalg.norm(p[inds[:,0]]-p[inds[:,1]],axis=1)
 return np.sum(np.maximum(rcut-d,0)**2)*100+.0005*np.sum(np.array(angs)**2)
res=differential_evolution(loss,[(-75,75),(-75,75)],seed=129,tol=1e-9)
print(res.x,res.fun)
p=transform(res.x)
with open('start.xyz','w') as f:
 f.write(f'{len(elems)}\nAuCl(Ge(pyridyl enolate)2)2 complex\n')
 for e,v in zip(elems,p):f.write(f'{e} {v[0]:.9f} {v[1]:.9f} {v[2]:.9f}\n')
d=np.linalg.norm(p[inds[:,0]]-p[inds[:,1]],axis=1)
for k in np.argsort(d-rcut)[:8]:print(inds[k], d[k],rcut[k])
